import { Ajv } from "ajv";
import standaloneCode from "ajv/dist/standalone/index.js";
import { brushPresetFileSchema, brushPresetSchema } from "../presets/schema.ts";
import {
  historyMessageSchema,
  patchMessageSchema,
  strokeMessageSchema,
  strokePresetSchema,
} from "../messages/schema.ts";
import { documentSchema } from "../document/schema.ts";

/** Header added to the generated validators file */
export const GENERATED_HEADER =
  "// Generated by packages/paintcanvas/scripts/build-validators.ts. Do not edit; run `pnpm --filter paintcanvas build:validators`.\n";

/**
 * Generate pre-compiled (standalone) ESM validator code for the brush preset, drawing message and document schemas, so validation never compiles
 * code at runtime (no `eval`/`new Function`, allowing a strict Content Security Policy).
 *
 * @example
 * writeFileSync("validators.generated.js", generateValidatorsCode());
 */
export const generateValidatorsCode = (): string => {
  const ajv = new Ajv({
    strict: true,
    allErrors: false,
    // Count string length in UTF-16 code units (no runtime helper import needed); limits are about size, not characters
    unicode: false,
    // Silences the deprecation notice for the `unicode` option
    logger: false,
    schemas: [
      brushPresetSchema,
      brushPresetFileSchema,
      strokePresetSchema,
      patchMessageSchema,
      strokeMessageSchema,
      historyMessageSchema,
      documentSchema,
    ],
    code: { source: true, esm: true },
  });
  return (
    GENERATED_HEADER +
    standaloneCode(ajv, {
      validateBrushPreset: brushPresetSchema.$id,
      validateBrushPresetFile: brushPresetFileSchema.$id,
      validatePatchMessage: patchMessageSchema.$id,
      validateStrokeMessage: strokeMessageSchema.$id,
      validateHistoryMessage: historyMessageSchema.$id,
      validateDocument: documentSchema.$id,
    })
  );
};
